#define pi acos(-1.)
#define tau (2. * pi)

float balls(vec2 p){
    float k = 8., 
          // anime parameters
          a = tanh(cos(iTime * 3.) * 4. - 3.) * .5,
          b = tanh(cos(iTime * 2.) * 4. + 3.) * .4 + .4,
          c = tanh(cos(iTime * .5) * 3.) * .8,

          // calc curve
          dx = iTime * .4,
          dy = smoothstep(1., 0., b * abs(a + dx + floor((p.x - dx) * k) / k)) * c;

    p -= vec2(dx, dy);

    p = vec2(
            mod(p.x, 1. / k) - .5 / k,
            p.y
        );

    return length(p) - .05;
}

void mainImage(out vec4 o, vec2 u) {
    vec2 r = iResolution.xy;
    u = (u + u - r) / r.y;
    o = vec4(1);

    float d = balls(u);

    o -= sign(d) * vec4(1, 4, 7, 0) / 10.;
    o *= 1. - exp(- 3. * abs(d));
    o *= cos(100. * d) * .2 + .8;
    o += (1. - o) * smoothstep(4. / r.y, .0, abs(d));
}
